/**
 * Foto-galerij data — Judoclub Michigami.
 *
 * Structuur volgt de oude site (fotos.html): albums per onderwerp/toernooi,
 * jongste eerst. Recentere jaren (2024–2026) komen van Instagram.
 *
 * Foto's: thumbnail in het raster, `_orig`-versie (hoge kwaliteit) in de
 * lightbox via fullSrc / fullResSrc.
 */
export interface GalleryImage {
  src: string;
  caption: string;
  /** Hoogere-resolutie versie (bijv. _orig.jpg) — wordt gebruikt in de lightbox. */
  fullSrc?: string;
}

/** Afgeleide hoogere-resolutie src: x.jpg → x_orig.jpg (als die bestaat). */
export function fullResSrc(src: string): string {
  const m = src.match(/^(.*?)(\.\w+)$/);
  if (!m) return src;
  if (m[1].endsWith('_orig')) return src;
  return `${m[1]}_orig${m[2]}`;
}

export interface GalleryAlbum {
  id: string;
  title: string;
  /** Sorteervolgorde — kleiner = bovenaan. Archive krijgt 999 (altijd onderaan). */
  order: number;
  images: GalleryImage[];
}

